/* From Uiverse.io by shadowmurphy - Tags: green, loader, circle loader */
.__UIV_SCOPE__ .loader {
  position: relative;
  width: 600px;
  height: 600px;
  display: flex;
  justify-content: center;
  align-items: center;
}

.__UIV_SCOPE__ .circle {
  position: absolute;
  border-radius: 50%;
  animation-duration: 1.5s;
  animation-iteration-count: infinite;
  animation-timing-function: linear;
}

.__UIV_SCOPE__ .circle-1 {
  width: 60px;
  height: 60px;
  background: linear-gradient(109.8deg, rgba(52, 248, 35, 0.1855) 0%, rgba(68, 253, 38, 0.196) 100%);
  animation-name: circle-1-animation;
}

.__UIV_SCOPE__ .circle-3 {
  width: 40px;
  height: 40px;
  background: linear-gradient(109.8deg, rgba(52, 248, 35, 0.265) 0%, rgba(68, 253, 38, 0.28) 100%);
  animation-name: circle-3-animation;
}

.__UIV_SCOPE__ .circle-4 {
  width: 20px;
  height: 20px;
  background: linear-gradient(109.8deg, rgba(52, 248, 35, 0.265) 0%, rgba(68, 253, 38, 0.28) 100%);
  animation-name: circle-4-animation;
}

@keyframes circle-1-animation {
  0% {
    transform: scale(1);
  }

  50% {
    transform: scale(1.2);
  }

  100% {
    transform: scale(1);
  }
}

@keyframes circle-2-animation {
  0% {
    transform: scale(1);
  }

  50% {
    transform: scale(1.2);
  }

  100% {
    transform: scale(1);
  }
}

@keyframes circle-3-animation {
  0% {
    transform: scale(1);
  }

  50% {
    transform: scale(1.2);
  }

  100% {
    transform: scale(1);
  }
}

@keyframes circle-4-animation {
  0% {
    transform: scale(1);
  }

  50% {
    transform: scale(1.2);
  }

  100% {
    transform: scale(1);
  }
}
